    tipo:'Construto', raridade:'rara', fonte:'Ameaças de Arton', pagina:300,
    icone:'ti-cpu', cor:'#5c5c66',
    atributos:'+1 em três atributos diferentes (exceto Carisma)', penalidade:'Carisma –2',
